/**
 * Central helpers for prefers-reduced-motion (WCAG 2.3.3).
 * Use for canvas/JS; pair with @media (prefers-reduced-motion: reduce) in CSS.
 */
export const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)" as const;

export function getReducedMotionPreference(): boolean {
  if (typeof window === "undefined") return false;
  try {
    return window.matchMedia(REDUCED_MOTION_QUERY).matches;
  } catch {
    return false;
  }
}

/** Subscribe to OS/browser reduced-motion changes. */
export function subscribePrefersReducedMotion(onChange: (reduced: boolean) => void): () => void {
  if (typeof window === "undefined") return () => {};
  const mq = window.matchMedia(REDUCED_MOTION_QUERY);
  const handler = () => onChange(mq.matches);
  if (typeof mq.addEventListener === "function") {
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }
  mq.addListener(handler);
  return () => mq.removeListener(handler);
}
